<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/includes/bootstrap.php';
$user = require_auth('admin');
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action=(string)($_POST['action']??''); $entityId=filter_input(INPUT_POST,'entity_id',FILTER_VALIDATE_INT);
    if ($action==='verify_user') { db()->prepare('UPDATE users SET verified_at=NOW() WHERE id=? AND role="landlord"')->execute([$entityId]); audit('admin.user_verified','user',$entityId); flash('success','Landlord verified.'); }
    elseif ($action==='verify_property') { db()->prepare('UPDATE properties SET verified_at=NOW(), status="published" WHERE id=?')->execute([$entityId]); audit('admin.property_verified','property',$entityId); flash('success','Property verified and published.'); }
    elseif (in_array($action,['approve_document','reject_document'],true)) { $status=$action==='approve_document'?'approved':'rejected'; db()->prepare('UPDATE user_documents SET status=?, reviewed_by=?, reviewed_at=NOW() WHERE id=?')->execute([$status,$user['id'],$entityId]); audit('admin.document_'.$status,'document',$entityId); flash('success','Document review saved.'); }
    redirect('admin.php');
}
$metrics=[
 'users'=>(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn(),
 'properties'=>(int)db()->query('SELECT COUNT(*) FROM properties')->fetchColumn(),
 'bookings'=>(int)db()->query('SELECT COUNT(*) FROM bookings')->fetchColumn(),
 'held'=>(float)db()->query("SELECT COALESCE(SUM(amount),0) FROM escrow_transactions WHERE status='held'")->fetchColumn(),
];
$landlords=db()->query("SELECT id,first_name,last_name,email,verified_at FROM users WHERE role='landlord' ORDER BY verified_at IS NULL DESC,created_at DESC")->fetchAll();
$properties=db()->query("SELECT p.id,p.title,p.city,p.status,p.verified_at,CONCAT(u.first_name,' ',u.last_name) landlord FROM properties p JOIN users u ON u.id=p.landlord_id ORDER BY p.verified_at IS NULL DESC,p.created_at DESC")->fetchAll();
$documents=db()->query("SELECT d.id,d.original_name,d.status,d.uploaded_at,CONCAT(u.first_name,' ',u.last_name) owner FROM user_documents d JOIN users u ON u.id=d.user_id ORDER BY d.status='pending' DESC,d.uploaded_at DESC")->fetchAll();
$logs=db()->query('SELECT a.action,a.entity_type,a.entity_id,a.created_at,COALESCE(u.email,"system") actor FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 12')->fetchAll();
$pageTitle='Administrator dashboard'; require dirname(__DIR__) . '/app/includes/header.php';
?>
<section class="dashboard-head section"><div><p class="eyebrow">Administrator control</p><h1>Platform assurance.</h1><p>Review verification evidence and monitor critical actions.</p></div><a class="button" href="<?= e(url('reports.php')) ?>">Generate reports</a></section>
<section class="section metric-row four"><article><span>Users</span><strong><?= $metrics['users'] ?></strong></article><article><span>Properties</span><strong><?= $metrics['properties'] ?></strong></article><article><span>Bookings</span><strong><?= $metrics['bookings'] ?></strong></article><article><span>Simulated funds held</span><strong><?= money($metrics['held']) ?></strong></article></section>
<section class="section admin-sections"><div class="panel"><h2>Landlord verification</h2><?php foreach($landlords as $landlord):?><div class="admin-row"><div><strong><?= e($landlord['first_name'].' '.$landlord['last_name']) ?></strong><span><?= e($landlord['email']) ?></span></div><?php if($landlord['verified_at']):?><span class="status status-completed">Verified</span><?php else:?><form method="post"><?= csrf_field() ?><input type="hidden" name="entity_id" value="<?= (int)$landlord['id'] ?>"><input type="hidden" name="action" value="verify_user"><button class="button button-small">Verify</button></form><?php endif;?></div><?php endforeach;?></div><div class="panel"><h2>Property verification</h2><?php foreach($properties as $property):?><div class="admin-row"><div><strong><?= e($property['title']) ?></strong><span><?= e($property['city'].' · '.$property['landlord']) ?></span></div><?php if($property['verified_at']):?><span class="status status-completed">Published</span><?php else:?><form method="post"><?= csrf_field() ?><input type="hidden" name="entity_id" value="<?= (int)$property['id'] ?>"><input type="hidden" name="action" value="verify_property"><button class="button button-small">Verify</button></form><?php endif;?></div><?php endforeach;?></div><div class="panel"><h2>Document review</h2><?php foreach($documents as $document):?><div class="admin-row"><div><strong><?= e($document['owner']) ?></strong><span><?= e($document['original_name']) ?></span></div><?php if($document['status']==='pending'):?><div class="action-row"><form method="post"><?= csrf_field() ?><input type="hidden" name="entity_id" value="<?= (int)$document['id'] ?>"><input type="hidden" name="action" value="approve_document"><button class="button button-small">Approve</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="entity_id" value="<?= (int)$document['id'] ?>"><input type="hidden" name="action" value="reject_document"><button class="button button-small button-danger">Reject</button></form></div><?php else:?><span class="status status-<?= e($document['status']==='approved'?'completed':'rejected') ?>"><?= e(ucfirst($document['status'])) ?></span><?php endif;?></div><?php endforeach;?></div><div class="panel dark"><h2>Recent audit events</h2><?php foreach($logs as $log):?><div class="audit-row"><code><?= e($log['action']) ?></code><span><?= e($log['actor']) ?> · <?= e(date('d M H:i',strtotime($log['created_at']))) ?></span></div><?php endforeach;?></div></section>
<?php require dirname(__DIR__) . '/app/includes/footer.php'; ?>
